<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50 pb-safe">
		<!-- ============ HEADER ============ -->
		<div
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<RouterLink
					:to="{ name: 'TebusMotor' }"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-ui-action transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					title="Kembali"
					aria-label="Kembali"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>
				<span class="min-w-0 truncate font-medium text-ui-ink-gray-900"
					>Tambah Tebus Motor Nasabah</span
				>
			</div>
		</div>

		<div class="flex flex-1 flex-col">
			<p v-if="!metaFields.length && !metaError" class="px-6 py-4 text-sm text-ui-ink-gray-500">
				Memuat form…
			</p>
			<pre
				v-else-if="metaError"
				class="px-6 py-4 text-sm text-ui-ink-red-600 whitespace-pre-wrap"
				>{{ metaError }}</pre
			>

			<!-- ============ FORM ============ -->
			<div v-else class="app-container-narrow px-4 py-5 text-base md:px-6">
				<pre
					v-if="saveError"
					class="mb-4 rounded-md border border-ui-line-red-200 bg-ui-surface-red-50 px-3 py-2 text-sm text-ui-ink-red-700 whitespace-pre-wrap"
					>{{ saveError }}</pre
				>

				<div class="space-y-4">
					<section
						v-for="(sec, si) in sections"
						:key="si"
						class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
					>
						<h3 v-if="sec.label" class="mb-3 text-lg font-semibold text-primary">
							{{ sec.label }}
						</h3>
						<div class="flex flex-col gap-x-6 gap-y-4 md:flex-row">
							<div
								v-for="(col, ci) in sec.columns"
								:key="ci"
								class="flex-1 space-y-4"
							>
								<div v-for="field in col" :key="field.fieldname">
									<label class="mb-1 block text-base font-medium text-ui-ink-gray-500">
										{{ field.label }}
										<span v-if="field.reqd" class="text-ui-ink-red-500">*</span>
									</label>

									<!-- ===== READ-ONLY (hasil fetch_from) → teks terkunci ===== -->
									<template v-if="field.read_only">
										<p
											v-if="field.fieldtype === 'Currency'"
											class="min-h-[1.25rem] text-base font-medium text-ui-ink-gray-900"
										>
											{{ currencyDisplay(form[field.fieldname]) || '—' }}
										</p>
										<p
											v-else-if="field.fieldtype === 'Date'"
											class="min-h-[1.25rem] text-base text-ui-ink-gray-800"
										>
											{{ formatDateDisplay(form[field.fieldname]) || '—' }}
										</p>
										<p
											v-else
											class="min-h-[1.25rem] break-words text-base text-ui-ink-gray-800"
										>
											{{
												form[field.fieldname] == null ||
												form[field.fieldname] === ''
													? '—'
													: form[field.fieldname]
											}}
										</p>
									</template>

									<!-- ===== EDITABLE ===== -->
									<template v-else>
										<!-- Select -->
										<SelectMenu
											v-if="field.fieldtype === 'Select'"
											v-model="form[field.fieldname]"
											:options="selectOptions(field)"
											:clearable="!field.reqd"
											placeholder="Pilih…"
											:btn-class="inputClass"
										/>

										<!-- Date -->
										<input
											v-else-if="field.fieldtype === 'Date'"
											v-model="form[field.fieldname]"
											type="date"
											:class="inputClass"
										/>

										<!-- Currency -->
										<input
											v-else-if="field.fieldtype === 'Currency'"
											type="text"
											inputmode="decimal"
											:value="currencyDisplay(form[field.fieldname])"
											:class="inputClass"
											@focus="
												$event.target.value = form[field.fieldname] ?? ''
											"
											@blur="onCurrencyBlur(field, $event)"
										/>

										<!-- Int/Float -->
										<input
											v-else-if="isNumberField(field.fieldtype)"
											v-model="form[field.fieldname]"
											type="number"
											inputmode="decimal"
											:class="inputClass"
										/>

										<!-- Small Text -->
										<textarea
											v-else-if="isTextarea(field.fieldtype)"
											v-model="form[field.fieldname]"
											rows="3"
											:class="[inputClass, 'resize-none']"
										/>

										<!-- Link → dropdown searchable (motor_tarikan dkk) -->
										<div
											v-else-if="field.fieldtype === 'Link'"
											class="relative"
										>
											<button
												type="button"
												:class="[
													inputClass,
													'flex items-center justify-between gap-2 text-left',
												]"
												@click="toggleLinkDropdown(field)"
											>
												<span
													class="min-w-0 truncate font-bold text-ui-ink-gray-900"
												>
													{{ form[field.fieldname] || 'Pilih…' }}
												</span>
												<svg
													xmlns="http://www.w3.org/2000/svg"
													viewBox="0 0 24 24"
													class="h-4 w-4 shrink-0 text-ui-ink-gray-400"
													fill="none"
													stroke="currentColor"
													stroke-width="2"
													stroke-linecap="round"
													stroke-linejoin="round"
												>
													<path d="m6 9 6 6 6-6" />
												</svg>
											</button>

											<div
												v-if="openDropdown === field.fieldname"
												class="absolute left-0 right-0 z-20 mt-1.5 overflow-hidden rounded-xl border border-ui-line-gray-200 bg-ui-surface shadow-xl ring-1 ring-black/5"
											>
												<div class="border-b border-ui-line-gray-100 p-2">
													<input
														v-model="linkSearch"
														type="text"
														placeholder="Cari…"
														:class="inputClass"
														@click.stop
														@input="onLinkSearch(field)"
													/>
												</div>
												<div class="max-h-56 overflow-y-auto p-1">
													<button
														v-for="opt in linkResults"
														:key="opt.value"
														type="button"
														class="flex w-full flex-col items-start rounded-lg px-3 py-2 text-left transition"
														:class="
															String(opt.value) ===
															String(form[field.fieldname])
																? 'bg-ui-surface-gray-100'
																: 'hover:bg-ui-surface-gray-50'
														"
														@click="
															selectLink(field, opt.value, opt.label)
														"
													>
														<span class="font-bold text-ui-ink-gray-900">{{
															opt.label
														}}</span>
														<span
															v-if="opt.value !== opt.label"
															class="text-xs text-ui-ink-gray-400"
															>{{ opt.value }}</span
														>
													</button>
													<p
														v-if="!linkResults.length"
														class="px-3 py-2 text-xs text-ui-ink-gray-400"
													>
														{{
															linkSearchLoading
																? 'Mencari…'
																: 'Tidak ada hasil'
														}}
													</p>
												</div>
											</div>
										</div>

										<!-- Default: teks -->
										<input
											v-else
											v-model="form[field.fieldname]"
											type="text"
											:class="inputClass"
										/>
									</template>
								</div>
							</div>
						</div>
					</section>
				</div>

				<div v-if="openDropdown" class="fixed inset-0 z-10" @click="openDropdown = ''" />
			</div>
		</div>

		<!-- ====== Action bar Cancel / Save ====== -->
		<div
			class="sticky bottom-0 z-20 flex gap-2 border-t border-ui-line-gray-200 bg-ui-surface px-4 py-3 md:px-6 bottom-bar"
		>
			<RouterLink
				:to="{ name: 'TebusMotor' }"
				class="flex flex-1 items-center justify-center rounded-lg border border-ui-line-gray-300 bg-ui-surface py-2.5 text-sm font-medium text-ui-ink-gray-700"
			>
				Cancel
			</RouterLink>
			<button
				type="button"
				:disabled="saving"
				class="flex flex-1 items-center justify-center rounded-lg bg-primary py-2.5 text-sm font-medium text-ui-onPrimary transition hover:opacity-90 disabled:opacity-50"
				@click="submit"
			>
				{{ saving ? 'Menyimpan…' : 'Save' }}
			</button>
		</div>
	</div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { refreshCsrfToken } from '../data/session'
import { MOTOR_TARIKAN_FILTERS } from '../data/tebusMotorStatus'
import { notifyError, notifySuccess } from '../composables/toast'
import SelectMenu from '../components/SelectMenu.vue'

const router = useRouter()
const DOCTYPE = 'Tebus Motor Nasabah'

const form = reactive({ tanggal_tebus: today() })
const saving = ref(false)
const saveError = ref('')

const metaFields = ref([])
const metaError = ref('')

const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

function today() {
	const d = new Date()
	const m = String(d.getMonth() + 1).padStart(2, '0')
	const day = String(d.getDate()).padStart(2, '0')
	return `${d.getFullYear()}-${m}-${day}`
}

// Nilai "kosong" ala frappe.is_null (0 TIDAK dianggap kosong).
function isNullVal(v) {
	return v == null || v === ''
}

// Susun section → kolom → field dari meta. Aturan tampil = form desk saat CREATE:
//  - lewati field non-input, hidden, & child Table
//  - read_only + KOSONG → sembunyikan (muncul sendiri setelah fetch_from mengisi,
//    mis. setelah memilih Motor Tarikan)
//  - read_only + ADA isi → tampil sebagai teks terkunci
//  - selain itu → input editable
const sections = computed(() => {
	const secs = []
	let curSection = null
	let curCol = null
	for (const f of metaFields.value) {
		const ft = f.fieldtype
		if (ft === 'Section Break') {
			curCol = []
			curSection = { label: f.label || '', depends_on: f.depends_on, columns: [curCol] }
			secs.push(curSection)
			continue
		}
		if (ft === 'Column Break') {
			if (!curSection) {
				curCol = []
				curSection = { label: '', columns: [curCol] }
				secs.push(curSection)
			} else {
				curCol = []
				curSection.columns.push(curCol)
			}
			continue
		}
		if (
			[
				'HTML',
				'Button',
				'Heading',
				'Fold',
				'Image',
				'Barcode',
				'Table',
				'Attach',
				'Attach Image',
			].includes(ft)
		)
			continue
		if (f.hidden) continue
		if (f.read_only && isNullVal(form[f.fieldname])) continue
		if (f.depends_on && !evalCondition(f.depends_on)) continue
		if (!curSection) {
			curCol = []
			curSection = { label: '', columns: [curCol] }
			secs.push(curSection)
		}
		curCol.push(f)
	}
	return secs
		.filter((s) => evalCondition(s.depends_on))
		.map((s) => ({ ...s, columns: s.columns.filter((c) => c.length) }))
		.filter((s) => s.columns.length)
})

const allFields = computed(() => {
	const out = []
	for (const s of sections.value) for (const c of s.columns) for (const f of c) out.push(f)
	return out
})

function selectOptions(field) {
	return String(field.options || '')
		.split('\n')
		.map((s) => s.trim())
		.filter(Boolean)
}
function isTextarea(ft) {
	return ['Small Text', 'Text', 'Long Text'].includes(ft)
}
function isNumberField(ft) {
	return ['Int', 'Float', 'Percent'].includes(ft)
}

function evalCondition(expr) {
	if (!expr) return true
	try {
		const code = String(expr).replace(/^eval:/, '')
		const frappeShim = { session: { user: '' } }
		const in_list = (list, item) => Array.isArray(list) && list.includes(item)
		const cint = (v) => parseInt(v, 10) || 0
		const cstr = (v) => (v == null ? '' : String(v))
		const flt = (v) => parseFloat(v) || 0
		// eslint-disable-next-line no-new-func
		return !!new Function(
			'doc',
			'frappe',
			'in_list',
			'cint',
			'cstr',
			'flt',
			`return (${code})`
		)(form, frappeShim, in_list, cint, cstr, flt)
	} catch (e) {
		return true
	}
}

// ---- Currency ----
function currencyDisplay(v) {
	if (v === '' || v == null || Number.isNaN(Number(v))) return ''
	return `Rp ${new Intl.NumberFormat('id-ID', {
		minimumFractionDigits: 2,
		maximumFractionDigits: 2,
	}).format(Number(v))}`
}
function parseCurrency(str) {
	if (str == null) return ''
	const cleaned = String(str)
		.replace(/\./g, '')
		.replace(',', '.')
		.replace(/[^\d.]/g, '')
	if (cleaned === '') return ''
	const n = Number(cleaned)
	return Number.isNaN(n) ? '' : n
}
function onCurrencyBlur(field, e) {
	const n = parseCurrency(e.target.value)
	form[field.fieldname] = n
	e.target.value = currencyDisplay(n)
}
function formatDateDisplay(v) {
	if (!v) return ''
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}

// ---- Link dropdown + fetch_from ----
const openDropdown = ref('')
const linkSearch = ref('')
const linkResults = ref([])
const linkSearchLoading = ref(false)
let linkSearchTimer = null

// Filter khusus per field Link. motor_tarikan → filter set_query desk.
function filtersFor(field) {
	if (field.fieldname === 'motor_tarikan') return MOTOR_TARIKAN_FILTERS
	return []
}

function toggleLinkDropdown(field) {
	if (openDropdown.value === field.fieldname) {
		openDropdown.value = ''
		return
	}
	openDropdown.value = field.fieldname
	linkSearch.value = ''
	fetchLinkResults(field, '')
}

async function fetchLinkResults(field, query) {
	const dt = field.options
	linkSearchLoading.value = true
	linkResults.value = []
	try {
		const params = new URLSearchParams({
			doctype: dt,
			fields: JSON.stringify(['name']),
			limit_page_length: '20',
			order_by: 'modified desc',
		})
		const filters = [...filtersFor(field)]
		if (query) filters.push(['name', 'like', `%${query}%`])
		if (filters.length) params.set('filters', JSON.stringify(filters))
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		linkResults.value = (json.message || []).map((r) => ({
			value: String(r.name),
			label: String(r.name),
		}))
	} catch (e) {
		linkResults.value = []
		notifyError(e, 'Gagal memuat pilihan')
	} finally {
		linkSearchLoading.value = false
	}
}
function onLinkSearch(field) {
	clearTimeout(linkSearchTimer)
	linkSearchTimer = setTimeout(() => fetchLinkResults(field, linkSearch.value.trim()), 300)
}

function selectLink(field, value) {
	form[field.fieldname] = value
	openDropdown.value = ''
	applyFetchFrom(field, value)
}

// Tiru fetch_from Frappe: saat sebuah Link diisi, ambil field turunannya dari
// dokumen tertaut lalu isi ke form → field read-only-nya langsung muncul terisi.
async function applyFetchFrom(linkField, value) {
	const prefix = `${linkField.fieldname}.`
	const targets = metaFields.value.filter(
		(f) => typeof f.fetch_from === 'string' && f.fetch_from.startsWith(prefix)
	)
	if (!targets.length) return
	if (!value) {
		for (const t of targets) form[t.fieldname] = null
		return
	}
	const sourceFields = targets.map((t) => t.fetch_from.slice(prefix.length))
	try {
		const params = new URLSearchParams({
			doctype: linkField.options,
			filters: JSON.stringify({ name: value }),
			fieldname: JSON.stringify(sourceFields),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		if (!res.ok) return
		const data = (await res.json())?.message || {}
		for (const t of targets) {
			const src = t.fetch_from.slice(prefix.length)
			if (src in data) form[t.fieldname] = data[src]
		}
	} catch (e) {
		/* nilai tetap terisi server saat save (fallback) */
	}
}

async function loadMeta() {
	try {
		const res = await fetch(
			`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(DOCTYPE)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		const docs = json.docs || json.message?.docs || []
		const dt = docs.find((x) => x.name === DOCTYPE) || docs[0]
		metaFields.value = (dt && dt.fields) || []
		// Terapkan default field dari meta (mis. biaya_pick_up=0) bila belum diisi.
		for (const f of metaFields.value) {
			if (f.default != null && f.default !== '' && form[f.fieldname] === undefined) {
				if (f.default === 'Today' && f.fieldtype === 'Date') form[f.fieldname] = today()
				else if (f.fieldname !== 'tanggal_tebus') form[f.fieldname] = f.default
			}
		}
	} catch (e) {
		metaError.value = e.message || String(e)
	}
}

function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return arr
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* ignore */
	}
	return (json && (json.exception || json.message)) || ''
}

function validate() {
	const missing = []
	for (const f of allFields.value) {
		if (!f.reqd || f.read_only) continue
		const v = form[f.fieldname]
		if (v === undefined || v === null || v === '') missing.push(f.label || f.fieldname)
	}
	return missing
}

async function submit() {
	saveError.value = ''
	const missing = validate()
	if (missing.length) {
		saveError.value = `Lengkapi field wajib: ${missing.join(', ')}`
		notifyError(saveError.value, 'Data belum lengkap')
		window.scrollTo({ top: 0, behavior: 'smooth' })
		return
	}
	saving.value = true
	try {
		await refreshCsrfToken()
		const res = await fetch('/api/method/frappe.client.insert', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: { doctype: DOCTYPE, ...form } }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		notifySuccess('Tebus Motor Nasabah berhasil dibuat.')
		const name = json.message?.name
		if (name) router.push({ name: 'TebusMotorDetail', params: { name } })
		else router.push({ name: 'TebusMotor' })
	} catch (e) {
		saveError.value = e.message || String(e)
		notifyError(e, 'Gagal menyimpan')
		window.scrollTo({ top: 0, behavior: 'smooth' })
	} finally {
		saving.value = false
	}
}

onMounted(async () => {
	await refreshCsrfToken()
	await loadMeta()
})
</script>
